/**
 * A successful result.
 * @template T
 * @param {T} value
 * @returns {{ ok: true, value: T }}
 */
export function ok(value) {
  return { ok: true, value };
}

/**
 * A failed result. `error` is an error code from ERRORS in src/errors.js.
 * @param {string} error
 * @param {unknown} [details]
 * @returns {{ ok: false, error: string, details?: unknown }}
 */
export function fail(error, details) {
  return details === undefined ? { ok: false, error } : { ok: false, error, details };
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  NO_LINES: 'An invoice must have at least one line item.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  NOT_DRAFT: 'Only draft invoices can be modified.',
  LINE_NOT_FOUND: 'That SKU is not on this invoice.',
  DISCOUNT_INVALID: 'Discount percent must be a number between 0 and 100.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

